from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
 def __init__(self):super().__init__();self.ids=[];self.refs=[];self.images=[];self.t=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if tag=='a' and a.get('href','').startswith('#') and len(a['href'])>1:self.refs.append(a['href'][1:])
  if tag=='img':self.images.append(a)
 def handle_data(self,s):self.t.append(s)
p=Path('index.html');c=Check();c.feed(p.read_text());assert len(c.ids)==len(set(c.ids)),'Duplicate ids';assert not c.images,'Unexpected external images';assert set(c.refs)-set(c.ids)=={'sign-in'},set(c.refs)-set(c.ids)
